import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Esistenza di numeri non razionali e necessità di ampliare l'insieme","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/b_aritmetica-e-numeri/bc/bcj.md","filePath":"lezioni/b_aritmetica-e-numeri/bc/bcj.md"}`),a={name:`lezioni/b_aritmetica-e-numeri/bc/bcj.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="esistenza-di-numeri-non-razionali-e-necessita-di-ampliare-l-insieme-q" tabindex="-1">Esistenza di numeri non razionali e necessità di ampliare l&#39;insieme <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> <a class="header-anchor" href="#esistenza-di-numeri-non-razionali-e-necessita-di-ampliare-l-insieme-q" aria-label="Permalink to “Esistenza di numeri non razionali e necessità di ampliare l&#39;insieme”">​</a></h1><p>Sin dai primordi i numeri razionali furono usati per misurare, ma già dal quinto secolo avanti Cristo ci si accorse che esistevano grandezze la cui misura non poteva essere rappresentata da un numero razionale:</p><ul><li>la misura della diagonale di un quadrato rispetto al suo lato</li><li>la misura della circonferenza rispetto al suo diametro</li><li>la misura della diagonale di un cubo rispetto al suo lato</li><li>...</li></ul><p>Si ebbe quindi la necessità di definire un nuovo insieme di numeri, il problema però fu come fare a definire quei nuovi numeri partendo dai numeri già noti, cioè i numeri razionali?</p><p>Il problema fu risolto solamente nel 1876 da Dedekind.</p><hr><p>Segui tutto il ragionamento collegandoti a geometria a <a href="./../../../f/fn/fn.html">Teoria della misura</a></p>`,7)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};